 * Window bounds after applying a delta. Faithful mirror of
 * [`vibe_core::types::VibeWindowBounds`].
 */
public struct VibeFfiBounds {
    public var headTsMs: Int64
    public var tailTsMs: Int64
    public var hasMoreBefore: Bool
    public var hasMoreAfter: Bool
    /**
     * Live rows in the durable store for this chat — not the window length.
     */
    public var totalKnown: UInt64
    public var windowLen: UInt32

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(headTsMs: Int64, tailTsMs: Int64, hasMoreBefore: Bool, hasMoreAfter: Bool, 
        /**
         * Live rows in the durable store for this chat — not the window length.
         */totalKnown: UInt64, windowLen: UInt32) {
        self.headTsMs = headTsMs
        self.tailTsMs = tailTsMs
        self.hasMoreBefore = hasMoreBefore
        self.hasMoreAfter = hasMoreAfter
        self.totalKnown = totalKnown
        self.windowLen = windowLen
    }
}



extension VibeFfiBounds: Equatable, Hashable {
    public static func ==(lhs: VibeFfiBounds, rhs: VibeFfiBounds) -> Bool {
        if lhs.headTsMs != rhs.headTsMs {
            return false
        }
        if lhs.tailTsMs != rhs.tailTsMs {
            return false
        }
        if lhs.hasMoreBefore != rhs.hasMoreBefore {
            return false
        }
        if lhs.hasMoreAfter != rhs.hasMoreAfter {
            return false
        }
        if lhs.totalKnown != rhs.totalKnown {
            return false
        }
        if lhs.windowLen != rhs.windowLen {
            return false
        }
        return true
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(headTsMs)
        hasher.combine(tailTsMs)
        hasher.combine(hasMoreBefore)
        hasher.combine(hasMoreAfter)
        hasher.combine(totalKnown)
        hasher.combine(windowLen)
    }
}


