         */bounds: VibeFfiBounds, unreadCount: UInt32, firstUnreadId: String?) {
        self.chatId = chatId
        self.baseGeneration = baseGeneration
        self.generation = generation
        self.body = body
        self.bounds = bounds
        self.unreadCount = unreadCount
        self.firstUnreadId = firstUnreadId
    }
}



