/**
 * A delta is either an ordered op list or a full-snapshot reset.
 *
 * Kept as two variants rather than flattened to "ops, possibly empty": a
 * `Reset` is adopted by the consumer **regardless of generation**, and
 * collapsing it into an empty op list would silently drop that distinction and
 * leave a consumer stuck after a generation gap.
 */

public enum VibeFfiDeltaBody {
    
    case ops(ops: [VibeFfiOp]
    )
    case reset(window: VibeFfiWindow
    )
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeVibeFfiDeltaBody: FfiConverterRustBuffer {
    typealias SwiftType = VibeFfiDeltaBody

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> VibeFfiDeltaBody {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .ops(ops: try FfiConverterSequenceTypeVibeFfiOp.read(from: &buf)
        )
        
        case 2: return .reset(window: try FfiConverterTypeVibeFfiWindow.read(from: &buf)
        )
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: VibeFfiDeltaBody, into buf: inout [UInt8]) {
        switch value {
        
        
        case let .ops(ops):
            writeInt(&buf, Int32(1))
            FfiConverterSequenceTypeVibeFfiOp.write(ops, into: &buf)
            
        
        case let .reset(window):
            writeInt(&buf, Int32(2))
            FfiConverterTypeVibeFfiWindow.write(window, into: &buf)
            
        }
    }
}


